try {
  const { parse } = require('pg-connection-string');
  const dbConfig = parse(process.env.DATABASE_URL);

  if (!dbConfig.host || !dbConfig.user || !dbConfig.database) {
    throw new Error('Missing required fields in DATABASE_URL');
  }
