// Secure Express Application
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const createError = require('http-errors');

const app = express();

// ====== SECURITY MIDDLEWARE ======
app.use(helmet()); // Security headers
app.use(cors({ origin: process.env.ALLOWED_ORIGINS?.split(',') || '*' })); // CORS

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
});
app.use(limiter);

// Trust proxy (if behind reverse proxy like Nginx)
app.set('trust proxy', true);

// ====== PARSING & VALIDATION ======
app.use(express.json()); // Parse JSON bodies
app.use(express.urlencoded({ extended: true })); // Parse URL-encoded bodies

// ====== ROUTES ======
app.get('/health', (req, res, next) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  } catch (err) {
    next(err); // Pass errors to centralized handler
  }
});

app.get(
  '/users',
  [
    // Validate query params (example: ?filter=active)
    query('filter').optional().isIn(['active', 'inactive']).escape(),
  ],
  (req, res, next) => {
    try {
      // Check for validation errors
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        throw createError(400, 'Invalid query parameters', { errors: errors.array() });
      }

      // Sample user data (in a real app, fetch from DB)
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter users if query param is provided
      const { filter } = req.query;
      const filteredUsers = filter ? users.filter(user => user.status === filter) : users;

      res.json(filteredUsers);
    } catch (err) {
      next(err);
    }
  }
);

// ====== ERROR HANDLING ======
// 404 Handler
app.use((req, res, next) => {
  next(createError(404, 'Route not found'));
});

// Centralized error handler
app.use((err, req, res, next) => {
  // Log error (use a logging library like Winston in production)
  console.error(err);

  // Send error response
  res.status(err.status || 500).json({
    error: {
      message: process.env.NODE_ENV === 'development' ? err.message : 'Internal Server Error',
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack }), // Only in dev
    },
  });
});

// ====== START SERVER ======
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

