// Script to verify connectivity to services using credentials in .env.test

require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg'); // For PostgreSQL
const AWS = require('aws-sdk');
const Stripe = require('stripe');
const fetch = require('node-fetch');

// Test PostgreSQL Connection
async function testPostgreSQL() {
  console.log('\n=== Testing PostgreSQL Connection ===');
  const client = new Client({
    connectionString: process.env.DATABASE_URL,
  });

  try {
    await client.connect();
    console.log('✅ PostgreSQL: Connection successful');
    const res = await client.query('SELECT 1');
    console.log('✅ PostgreSQL: Query successful:', res.rows);
  } catch (err) {
    console.error('❌ PostgreSQL: Connection failed:', err.message);
  } finally {
    await client.end();
  }
}

// Test AWS Credentials
async function testAWS() {
  console.log('\n=== Testing AWS Credentials ===');
  const awsConfig = {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    region: 'us-east-1', // Default region
  };

  const sts = new AWS.STS(awsConfig);

  try {
    const data = await sts.getCallerIdentity().promise();
    console.log('✅ AWS: Credentials valid. Account ID:', data.Account);
  } catch (err) {
    console.error('❌ AWS: Credentials invalid:', err.message);
  }
}

// Test Stripe API Key
async function testStripe() {
  console.log('\n=== Testing Stripe API Key ===');
  const stripe = Stripe(process.env.STRIPE_SECRET_KEY);

  try {
    const balance = await stripe.balance.retrieve();
    console.log('✅ Stripe: API key valid. Balance:', balance);
  } catch (err) {
    console.error('❌ Stripe: API key invalid:', err.message);
  }
}

// Test Anthropic API Key
async function testAnthropic() {
  console.log('\n=== Testing Anthropic API Key ===');
  const apiKey = process.env.ANTHROPIC_API_KEY;

  try {
    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-API-Key': apiKey,
        'anthropic-version': '2023-06-01',
      },
      body: JSON.stringify({
        model: 'claude-3-haiku-20240307',
        max_tokens: 1,
        messages: [{ role: 'user', content: 'Hello' }],
      }),
    });

    if (response.ok) {
      console.log('✅ Anthropic: API key valid');
    } else {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }
  } catch (err) {
    console.error('❌ Anthropic: API key invalid:', err.message);
  }
}

// Test Logfire Token
async function testLogfire() {
  console.log('\n=== Testing Logfire Token ===');
  const token = process.env.LOGFIRE_TOKEN;

  try {
    const response = await fetch('https://in.logfire.ai/api/v1/projects', {
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${token}`,
      },
    });

    if (response.ok) {
      console.log('✅ Logfire: Token valid');
    } else {
      throw new Error(`HTTP ${response.status}: ${response.statusText}`);
    }
  } catch (err) {
    console.error('❌ Logfire: Token invalid:', err.message);
  }
}

// Run all tests
(async () => {
  await testPostgreSQL();
  await testAWS();
  await testStripe();
  await testAnthropic();
  await testLogfire();
})();

