require('dotenv').config({ path: '.env.test' });
const https = require('https');
const { readFileSync } = require('fs');

// Helper: Make HTTPS GET request
function testApiKey(url, apiKey, authHeader = 'Authorization') {
  return new Promise((resolve) => {
    const options = {
      method: 'GET',
      headers: {
        [authHeader]: `Bearer ${apiKey}`,
      },
    };

    const req = https.request(url, options, (res) => {
      let data = '';
      res.on('data', (chunk) => (data += chunk));
      res.on('end', () => {
        resolve({
          url,
          status: res.statusCode,
          valid: res.statusCode === 200,
          data: data || undefined,
        });
      });
    });

    req.on('error', (error) => {
      resolve({ url, status: 'ERROR', valid: false, error: error.message });
    });
    req.end();
  });
}

// Helper: Test Stripe (uses Basic Auth)
function testStripe(stripeKey) {
  return new Promise((resolve) => {
    const options = {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${stripeKey}`,
      },
    };

    const req = https.request('https://api.stripe.com/v1/charges', options, (res) => {
      let data = '';
      res.on('data', (chunk) => (data += chunk));
      res.on('end', () => {
        resolve({
          url: 'https://api.stripe.com/v1/charges',
          status: res.statusCode,
          valid: res.statusCode === 200,
          data: data || undefined,
        });
      });
    });

    req.on('error', (error) => {
      resolve({ url: 'https://api.stripe.com/v1/charges', status: 'ERROR', valid: false, error: error.message });
    });
    req.end();
  });
}

