      test: () => testStripe(process.env.STRIPE_SECRET_KEY),
    },
    {
      name: 'Logfire Token (skip if no endpoint)',
      test: () => Promise.resolve({ skipped: true }),
    },
  ];

  for (const test of tests) {
    console.log(`Testing: ${test.name}`);
    try {
      const result = await test.test();
      console.log(`  Result: ${result.valid ? '✅ VALID' : result.skipped ? '⚠️  SKIPPED' : '❌ INVALID'}`);
