const { Client } = require('pg'); // For PostgreSQL connection
const { parse } = require('url');

// Load environment variables from .env.test
require('dotenv').config({ path: '.env.test' });

// Validate database connection (format + host/port reachability)
async function testDatabaseConnection() {
  const dbUrl = process.env.DATABASE_URL;
  if (!dbUrl) {
    console.log('[SKIP] DATABASE_URL not set.');
    return;
  }

  try {
    const parsed = parse(dbUrl);
    const [host, port] = parsed.host?.split(':') || [];
    const database = parsed.pathname?.substring(1);

    if (!host || !port || !database) {
      throw new Error('Invalid DATABASE_URL format.');
    }

    console.log(`[OK] DATABASE_URL format is valid: postgres://<REDACTED>@${host}:${port}/${database}`);

    // Test connection (without authentication)
    const client = new Client({ connectionString: dbUrl, ssl: { rejectUnauthorized: false } });
    await client.connect();
    console.log('[OK] Database host/port are reachable.');
    await client.end();
  } catch (err) {
    console.log(`[FAIL] Database connection check failed: ${err.message}`);
  }
}

// Check AWS keys (format only, no live API calls)
function testAwsKeys() {
  const awsKey = process.env.AWS_ACCESS_KEY_ID;
  const awsSecret = process.env.AWS_SECRET_ACCESS_KEY;

  if (!awsKey || !awsSecret) {
    console.log('[SKIP] AWS keys not set.');
    return;
  }

  const keyRegex = /^[A-Z0-9]{20}$/;
  if (!keyRegex.test(awsKey)) {
    console.log('[FAIL] AWS_ACCESS_KEY_ID format is invalid.');
  } else {
    console.log('[OK] AWS_ACCESS_KEY_ID format is valid.');
  }
}

// Check Anthropic API key (format only)
