  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) {
    console.log('[SKIP] ANTHROPIC_API_KEY not set.');
    return;
  }

  const keyRegex = /^sk-ant-[a-zA-Z0-9-]{10,}$/;
  if (!keyRegex.test(key)) {
    console.log('[FAIL] ANTHROPIC_API_KEY format is invalid.');
  } else {
    console.log('[OK] ANTHROPIC_API_KEY format is valid.');
  }
}

// Run all tests
