#!/usr/bin/env node

const { Client } = require('pg');
const AWS = require('aws-sdk');
const stripe = require('stripe');
const https = require('https');

envVariables = {
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
};

// REDACT sensitive values in logs
function redact(str) {
  if (!str) return 'undefined';
  return str.replace(/:[^@:\/\s]+@/, ':****@') // Redact passwords in URLs
    .replace(/\w{5,}/g, (match) => match.length > 8 ? '***' : match); // Redact tokens
}

// Test PostgreSQL connection
async function testPostgres() {
  if (!envVariables.DATABASE_URL) {
    return { valid: false, error: 'DATABASE_URL not set' };
  }
  const client = new Client({ connectionString: envVariables.DATABASE_URL });
  try {
    await client.connect();
    await client.query('SELECT 1');
    return { valid: true, message: 'PostgreSQL connection succeeded' };
  } catch (error) {
    return { valid: false, error: `PostgreSQL error: ${error.message}` };
  } finally {
    await client.end();
  }
}

// Test AWS credentials
async function testAWS() {
  if (!envVariables.AWS_ACCESS_KEY_ID || !envVariables.AWS_SECRET_ACCESS_KEY) {
    return { valid: false, error: 'AWS credentials not set' };
  }
  const sts = new AWS.STS();
  try {
    await sts.getCallerIdentity({}).promise();
    return { valid: true, message: 'AWS credentials valid' };
  } catch (error) {
    return { valid: false, error: `AWS error: ${error.message}` };
  }
}

// Test Anthropic API key
async function testAnthropic() {
  if (!envVariables.ANTHROPIC_API_KEY) {
    return { valid: false, error: 'ANTHROPIC_API_KEY not set' };
  }
  const options = {
    hostname: 'api.anthropic.com',
    path: '/v1/messages',
    method: 'POST',
    headers: {
      'x-api-key': envVariables.ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01',
      'Content-Type': 'application/json',
    },
  };
  return new Promise((resolve) => {
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => data += chunk);
      res.on('end', () => {
        if (res.statusCode === 200) {
          resolve({ valid: true, message: 'Anthropic API key valid' });
        } else {
          resolve({ valid: false, error: `Anthropic error: ${res.statusCode} ${data}` });
        }
      });
    });
    req.on('error', (error) => resolve({ valid: false, error: `Anthropic error: ${error.message}` }));
    req.write(JSON.stringify({
      model: 'claude-3-haiku-20240307',
      max_tokens: 1,
      messages: [{ role: 'user', content: 'Hello' }],
    }));
    req.end();
  });
}

// Test Stripe secret key
async function testStripe() {
  if (!envVariables.STRIPE_SECRET_KEY) {
    return { valid: false, error: 'STRIPE_SECRET_KEY not set' };
  }
  const stripeClient = stripe(envVariables.STRIPE_SECRET_KEY);
  try {
    await stripeClient.charges.list({ limit: 1 });
    return { valid: true, message: 'Stripe key valid' };
  } catch (error) {
    return { valid: false, error: `Stripe error: ${error.message}` };
  }
}

// Run all tests
async function runTests() {
  console.log('Testing environment variables...\n');

  const tests = {
    DATABASE_URL: await testPostgres(),
    AWS: await testAWS(),
    ANTHROPIC_API_KEY: await testAnthropic(),
    STRIPE_SECRET_KEY: await testStripe(),
  };

  for (const [key, result] of Object.entries(tests)) {
    console.log(`\n${key}:`);
    console.log(`  Value: ${redact(envVariables[key])}`);
    console.log(`  Valid: ${result.valid}`);
    if (result.message) console.log(`  Message: ${result.message}`);
    if (result.error) console.log(`  Error: ${result.error}`);
  }
}

runTests();
